// Synthetic original PDF bytes only; no runtime/document/provider input.
function pdf(objects){let text='%PDF-1.7\n';const offsets=[0];objects.forEach((o,i)=>{offsets.push(Buffer.byteLength(text));text+=`${i+1} 0 obj\n${o}\nendobj\n`});const x=Buffer.byteLength(text);text+=`xref\n0 ${objects.length+1}\n0000000000 65535 f \n`+offsets.slice(1).map(o=>String(o).padStart(10,'0')+' 00000 n \n').join('')+`trailer\n<< /Size ${objects.length+1} /Root 1 0 R >>\nstartxref\n${x}\n%%EOF\n`;return Buffer.from(text)}
function annotated({kind='Link',pages=1,action=false,unsafe=false,extra='',firstOnly=false}={}){const body='BT /F1 18 Tf 30 150 Td (OFFICE INVOICE 12345) Tj ET',objects=[`<< /Type /Catalog /Pages 2 0 R ${action?'/OpenAction << /S /JavaScript /JS (void 0) >>':''} >>`,`<< /Type /Pages /Kids [${Array.from({length:pages},(_,i)=>`${4+3*i} 0 R`).join(' ')}] /Count ${pages} >>`,'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>'];for(let i=0;i<pages;i++){objects.push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 300 220] /Resources << /Font << /F1 3 0 R >> >> /Contents ${5+3*i} 0 R ${firstOnly&&i>0?'':`/Annots [${6+3*i} 0 R]`} >>`,`<< /Length ${Buffer.byteLength(body)} >>\nstream\n${body}\nendstream`,`<< /Type /Annot /Subtype /${kind} /Rect [20 20 100 45] ${kind==='Link'?`/A << /S /URI /URI (${unsafe?'javascript:alert(1)':'https://example.invalid/SYNTHETIC'}) >>`:'/Contents (SYNTHETIC reviewer note) /Name /Comment'} ${extra} >>`);}return pdf(objects)}
function form({password=false,hidden=false,action=false,xfa=false,rich=false,button=false,appearance=false}={}){return pdf(['<< /Type /Catalog /Pages 2 0 R /AcroForm 4 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 300 200] /Annots [5 0 R] >>',`<< /Fields [5 0 R] /DA (/Helv 16 Tf 0 g) /DR << /Font << /Helv 6 0 R >> >> ${xfa?'/XFA 7 0 R':''} >>`,`<< /Type /Annot /Subtype /Widget /FT /${button?'Btn':'Tx'} /T (synthetic) /Rect [20 20 260 60] /P 3 0 R /F ${hidden?2:4} /Ff ${password?8192:rich?33554432:0} /V (OFFICE INVOICE 12345) ${appearance?'/AP << /N 8 0 R >>':''} ${rich?'/RV (<p>RICH PRIVATE</p>)':''} ${action?'/AA << /K << /S /JavaScript /JS (void 0) >> >>':''} >>`,'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>','<< /Length 10 >>\nstream\n<template>\nendstream',`<< /Type /XObject /Subtype /Form /BBox [0 0 240 40] /Resources << /Font << /Helv 6 0 R >> >> /Length 61 >>\nstream\nBT /Helv 16 Tf 10 10 Td (OFFICE INVOICE 12345) Tj ET\nendstream`])}

export {pdf,annotated,form};
